package io.todu.andjs.domain

object ExtendedApiCatalog {
    private fun field(name:String,type:String,description:String)=ApiArgument(name,if(name.startsWith("options.") && !type.contains("可选")) "$type，可选" else type,description)
    private val httpFields=listOf(
        field("status","number","HTTP 状态码。"),field("statusText","string","HTTP 状态文字，HTTP/2 下可能为空。"),field("ok","boolean","状态码是否为 200–299。"),field("url","string","最终 URL。"),
        field("headers","object<string, string[]>","小写响应头名称映射到值数组，保留 Set-Cookie 等重复头。"),field("contentType","string","响应内容类型，无此头为空字符串。"),
        field("isJson","boolean","HTTP 状态码为 200–299 且 auto/json 模式成功解析 JSON 时为 true（包括 JSON null、标量），无需再判断 ok；空响应、非 JSON、其它模式或 HTTP 失败为 false。"),field("isFile","boolean","HTTP 状态码为 200–299 且 file/download 模式完整写入本机文件后为 true，无需再判断 ok；其它模式或 HTTP 失败为 false。不校验文件业务内容；网络或写入失败抛错。"),field("size","number","已读取响应字节数。"),field("elapsedMs","number","整个请求耗时，包含重试等待，毫秒。"),field("attempts","number","实际尝试次数；正常未重试为 1。"),field("text","string，可选","auto/text/json 模式存在，按响应 charset 解码，默认 UTF-8。"),
        field("data","任意 JSON 类型，可选","默认 auto 模式：合法 JSON 自动解析为对象、数组或对应标量，否则为原始字符串；json 模式严格解析，空响应为 null，无效 JSON 抛错。"),field("base64","string，可选","仅 base64 模式存在。"),field("file","string，可选","仅 file/download 模式存在。这里只返回文件名，不是完整路径；使用 andjs.files 访问时拼接 app:/network/ + r.file。显示图片可直接调用 andjs.log.img(r, null, \"100%\")。")
    )
    private val httpArguments=listOf(field("url","string","完整 HTTPS URL。明文 HTTP 受 Android 系统策略限制。"),field("options","object，可选","配置如下；所有请求同步等待完整响应。"),
        field("options.method","string","request 的方法，默认 GET；快捷方法固定其对应方法。"),field("options.query","object<string, scalar | scalar[]>","URL 查询参数，数组生成重复参数，自动编码。"),field("options.headers","object<string, string | string[]>","请求头，数组生成重复头。"),
        field("options.auth","object，可选","{type:'basic', username:string, password:string} 或 {type:'bearer', token:string}。覆盖 Authorization 头。"),
        field("options.data / json / form / text / base64 / file / multipart","互斥","data 为发送数据，对象或数组自动转为 JSON 并默认使用 application/json，其他类型转为文本；json 为显式 JSON 值；form 为对象（值可数组）；text 为字符串；base64 为二进制编码；file 为下载目录中的文件名。GET/HEAD 不支持请求体。"),
        field("options.multipart","object[]","每项：name:string，value:标量 或 base64:string 或 file:string（三选一）；文件项可有 filename:string、contentType:string。最多 100 项。"),field("options.contentType","string，可选","覆盖 json/text/base64/file 默认类型；multipart 自动生成边界，勿自行覆盖其 Content-Type。"),
        field("options.responseType","string","auto（默认，自动解析 JSON，否则按文本读取）、text（保留原文）、json（严格解析）、base64（二进制编码）、file（下载到文件）。图片、PDF、压缩包等二进制内容请使用 file 或 base64；download 固定为 file 模式。"),field("options.timeout / connectTimeout / readTimeout / writeTimeout","number","毫秒，1–120000；默认总超时 30000，连接 10000，读写 30000。手表请求超时上限 15000 毫秒；手机与手表脚本总运行时长不限。"),
        field("options.followRedirects / throwOnHttpError","boolean","默认 true / false。默认非 2xx 正常返回；开启 throwOnHttpError 后抛出 HttpError，error.response 保留状态、头和原文。不跨协议重定向。"),
        field("options.cookies","boolean | string | object<string, string>","默认 true，使用当前客户端的会话 Cookie。false 禁用自动读取与保存；字符串如 sid=abc; lang=zh 或对象 {sid:'abc'} 指定本次请求 Cookie，与会话合并、同名覆盖，不写入会话。手动 Cookie 只发送到原始同源地址，不带到跨域重定向。不能同时指定 cookies 字符串/对象和 Cookie 请求头。"),
        field("options.retry","number | object","默认 0，不重试。数字为额外重试次数；对象支持 count、delayMs（默认 500）、maxDelayMs（默认 5000）、methods（默认 GET/HEAD/OPTIONS）、statuses（默认 408/429/500/502/503/504）。手机最多重试 5 次，手表 2 次；指数退避，遵守 Retry-After，等待超出 maxDelayMs 或剩余预算时返回最后结果。网络临时错误可重试，参数、证书、文件、解码错误不重试。写请求须显式加入 methods，确认服务端允许重复提交。"),
        field("options.totalTimeout","number","整个请求（包含全部重试与等待）的预算，手机默认/最大 120000 毫秒，手表 15000；最小 1。timeout 仍是每次尝试的上限。"),
        field("options.maxBytes","number","手机内存响应默认 8MB、最大 16MB；文件响应默认 100MB、最大 256MB。手表内存响应默认及最大 2MB，下载默认及最大 16MB。超出则失败，清除临时下载。"),field("options.filename / overwrite","string / boolean","file/download 模式：不传 filename 为临时文件，脚本结束、停止或报错后自动清理；传入 filename（如 photo.jpg）则保存在 app:/network/ 下，后续运行仍可访问。filename 只能是文件名，限字母数字、点、横线和下划线，不能传目录路径。overwrite 默认 false，同名文件存在时抛错；设为 true 允许覆盖。需要保留临时下载时，在脚本结束前用 files.copy 复制到其他路径。")
    )
    private val fileFields=listOf(field("name","string","文件或目录名。"),field("path","string","API 路径。"),field("exists","boolean","是否存在。"),field("isDirectory","boolean","是否为目录。"),field("size","number","文件大小（字节）；目录或不存在为 0。"),field("modifiedAt","number","修改时间 Unix 毫秒；不存在为 0。"))
    private fun api(id:String,category:ApiCategory,signature:String,summary:String,args:List<ApiArgument>,returns:String,example:String,fields:List<ApiArgument> = emptyList(),devices:String="通用") = ApiMethod(id,category,"andjs."+id.substringBefore('.'),signature,summary,args,returns,example,"可用",fields,devices)
    val methods = listOf("request","get","post","put","patch","delete","head","options","download").map {method->
        api("http.$method",ApiCategory.NETWORK,"andjs.http.$method(url, options)",if(method=="download") "同步下载到应用文件目录。" else "同步发送 ${if(method=="request") "HTTP" else method.uppercase()} 请求。",httpArguments,"响应对象，字段如下。TLS 使用系统证书校验；默认不重试。失败抛出 HttpError，可读取 name、message、code、phase、url、method、status、attempts、elapsedMs、retryable；有完整响应时还带 response。code 包括 INVALID_OPTIONS、DNS_ERROR、CONNECTION_ERROR、TLS_ERROR、TIMEOUT、NETWORK_ERROR、FILE_ERROR、RESPONSE_TOO_LARGE、HTTP_ERROR、INVALID_RESPONSE、REQUEST_ERROR；停止脚本直接结束执行。retryable 仅表示临时故障，不表示可安全重复写请求。",
            if(method=="download") "const r = andjs.http.download(\"https://example.com/photo.jpg\", {filename: \"photo.jpg\", overwrite: true});\nif (!r.isFile) exit(false);\nconst path = \"app:/network/\" + r.file;\nandjs.log.img(r, null, \"100%\");\n// 手机已授权共享存储时，可复制到下载目录：\n// andjs.files.copy(path, \"shared:/Download/photo.jpg\", true);\nexit(path);" else if(method=="post") "exit(andjs.http.post(\"https://example.com/api\", {data: {name: \"And JS\"}}));" else "exit(andjs.http.$method(\"https://example.com/\"));",httpFields)
    } + listOf(
        api("http.createClient",ApiCategory.NETWORK,"andjs.http.createClient(defaults)","创建具有独立 Cookie 和连接池的网络客户端。",
            listOf(field("defaults","object，可选","支持所有请求配置，以及 baseUrl。请求 headers/query 与默认值合并；头名称不区分大小写，条目设 null 可删除默认值；其余字段按请求覆盖，null 清除默认设置；data/json 的 null 仍作为 JSON null 发送。指定新请求体格式会替换默认请求体。"),
                field("defaults.baseUrl","string，可选","例如 https://example.com/api/，尾部斜杠影响相对地址解析。设置后只接受同源请求地址；重定向仍遵循 followRedirects。未设置时请求使用完整 URL。")),
            "返回具有 request/get/post/put/patch/delete/head/options/download/batch/setCookies/getCookies/clearCookies 的客户端。方法与 andjs.http 相同。客户端及 Cookie 只在本次运行有效；包含默认客户端，手机最多 8 个，手表 4 个；文件目录仍共享。",
            "const client = andjs.http.createClient({baseUrl: \"https://example.com/api/\", retry: 2});\nclient.setCookies(\"./\", {sid: \"your-session\"});\nexit(client.get(\"profile\"));"),
        api("http.batch",ApiCategory.NETWORK,"andjs.http.batch(requests, options)","以受限并发请求多个接口，按输入顺序返回每项结果。",
            listOf(field("requests","object[]","每项为 {url, method, ...请求配置}，不是嵌套 options。手机 1–20 项，手表 1–8 项；批次格式错误在发送前抛出。相同批次的下载 filename 不得重复。共享当前客户端 Cookie；有登录先后依赖的请求请顺序调用。"),
                field("options.concurrency","number","手机默认/最大 4，手表 2；最小 1。"),field("options.totalTimeout","number","含排队的整批预算；手机默认/最大 120000 毫秒，手表 15000，超时取消未完成任务并抛错。"),
                field("requests[].maxBytes","number","内存响应总预算手机 8MB、手表 1MB，先为每个文件请求预留手机 256KB、手表 64KB 错误正文空间；文件响应总预算手机 256MB、手表 16MB。未指定时按同类请求数量均分剩余预算；显式指定时总和不得超过预算。")),
            "数组，每项 {ok, response?, error?}。ok 要求 HTTP 成功且响应解析成功；单项网络或 HTTP 失败不取消其它请求。response 为通常的响应对象，error 为结构化错误。批次总超时/参数错误抛 HttpError。停止直接结束脚本。所有脚本代码仍同步执行，不产生后台 JS 回调。",
            "const results = andjs.http.batch([{url: \"https://example.com/a\"}, {url: \"https://example.com/b\", responseType: \"json\"}], {concurrency: 2});\nresults.forEach(r => {if (r.ok) console.log(r.response.data); else console.log(r.error.code);});"),
        api("http.setCookies",ApiCategory.NETWORK,"andjs.http.setCookies(url, cookies)","向当前客户端的会话写入 Cookie。",
            listOf(field("url","string","Cookie 所属地址；独立客户端支持相对地址。"),field("cookies","string | object<string, string>","Cookie 请求头形式，例如 sid=abc; lang=zh，或 {sid:'abc', lang:'zh'}。不是 Set-Cookie 属性串。每次最多 100 项，同名同路径覆盖；仅该主机，路径 /，HTTPS 地址自动标记 secure，不跨脚本保存。值需 ASCII，可自行编码。")),
            "undefined；会话最多保留 200 个 Cookie，超出时淘汰最早加入的。", "andjs.http.setCookies(\"https://example.com/\", {sid: \"your-session\"});"),
